<script lang="ts">
  import { onMount } from 'svelte'
  import { api } from '$lib/api'
  let rows: any[] = []; let error = ''; let filter = ''; let search = ''; let pageNumber = 1; let pages = 1; let total = 0; let loading = false
  async function load() { loading = true; error = ''; try { const params = new URLSearchParams({ page: String(pageNumber), limit: '20' }); if (filter) params.set('status', filter); if (search.trim()) params.set('q', search.trim()); const result = await api<{ data: any[]; pagination: { pages: number; total: number } }>(`/admin/forms?${params}`); rows = result.data; pages = Math.max(1, result.pagination.pages); total = result.pagination.total } catch (reason: any) { error = reason.message } finally { loading = false } }
  onMount(() => { void load() })
  async function archive(form: any) { try { await api(`/admin/forms/${form._id}/status`, { method: 'PATCH', body: JSON.stringify({ status: form.status === 'archived' ? 'draft' : 'archived' }) }); await load() } catch (reason: any) { error = reason.message } }
</script>
<main class="admin-content"><div class="page-title"><div><span class="kicker">CONTENT MODERATION</span><h1>Forms</h1><p>Review published forms and remove harmful content from public access.</p></div><span class="count-pill">{total} total</span></div>{#if error}<div class="notice error">{error}</div>{/if}<div class="toolbar"><input aria-label="Search form title or slug" placeholder="Search title or slug" bind:value={search} onkeydown={(event) => { if (event.key === 'Enter') { pageNumber = 1; void load() } }}/><select aria-label="Filter by status" bind:value={filter} onchange={() => { pageNumber = 1; void load() }}><option value="">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><button class="secondary-button" onclick={() => { pageNumber = 1; void load() }}>Search</button></div><section class="panel table-panel"><table><thead><tr><th>Form</th><th>Owner</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>{#each rows as form}<tr><td><b>{form.title}</b><small>/f/{form.slug}</small></td><td>{form.owner?.name || 'Unknown'}<small>{form.owner?.email || ''}</small></td><td><span class:green={form.status === 'published'} class="status-pill">{form.status}</span></td><td>{new Date(form.createdAt).toLocaleDateString()}</td><td><button class="text-action" onclick={() => archive(form)}>{form.status === 'archived' ? 'Restore' : 'Archive'}</button></td></tr>{/each}</tbody></table>{#if !rows.length}<p class="table-empty">{loading ? 'Loading forms…' : 'No forms found.'}</p>{/if}</section><div class="admin-pagination"><span>Page {pageNumber} of {pages}</span><div><button class="secondary-button" disabled={pageNumber <= 1 || loading} onclick={() => { pageNumber -= 1; void load() }}>Previous</button><button class="secondary-button" disabled={pageNumber >= pages || loading} onclick={() => { pageNumber += 1; void load() }}>Next</button></div></div></main>
